$(document).ready(function () {
    createSearch();

});

function createSearch() {
    var db = $('#search').data('db');
    var example = $('#search').data('example');
    var key = $('#search').data('tip');
    var ad = $('#search').data('lan');
    if (key==="\"\""){
        key = ""
    }
    var searchForm = "<form class='form-horizontal' style='margin: 0 auto' action='search' id='searchAllField' namespace='search' >" +
        "<div class='form-group' style='margin: 0 auto'>" +
        "<div class='row'>" +
        "<div class='col-md-2 col-md-offset-1' style='margin-right: 0;padding-right: 0;padding-left: 0'>" +
        "<select class='form-control' id='dbId'>" +
        "<option value='"+db+"' selected>"+db+"</option>" +
        // "<option value='BioProject'>BioProject</option>" +
        // "<option value='BioSample'>BioSample</option>" +
        "</select>" +
        "</div>" +
        "<div class='col-md-6' style='margin-right: 0;margin-left: 0; padding-left: 0;padding-right: 0'>" +
        "<input  id='searchTerm' name='searchTerm' class='form-control' value='"+key+"'/>" +
        "</div>" +
        "<div class='col-md-1' style='margin-right: 0;margin-left: 0; padding-left: 0;padding-right: 0'>" +
        "<button class='btn btn-info'  type='button' onclick='searchAllField()' style='padding: 9px 20px'><span class='glyphicon glyphicon-search'></span></button>" +
        "</div>" +
        "<div class='col-md-2' style='margin-right: 0;margin-left: 0; padding-left: 0;padding-right: 0'>" +
        "<button class='btn btn-info form-control' type='button' onclick='searchAdvanced()' href='search/advanced' style='width: 85px;text-align: center;'>"+ad+"</button>" +
        "</div>" +
        "</div>" +
        "<span id='example' class='text-center help-block col-md-9 col-md-offset-1' style=\"left: 20px;\">e.g., </span>" +
        "</div>" +
        "</form>";

    $(document).ready(function () {
        if (example !== undefined) {
            if (example.indexOf(",") > 0) {
                example = example.split(",");
                $.each(example, function (i, item) {
                    var link = "<a href='search?searchTerm=" + item + "'>" + item + "</a>; ";
                    var lastlink = "<a href='search?searchTerm=" + item + "'>" + item + "</a>";
                    if (example.length > 1) {
                        if (i === example.length - 1) {
                            $('span#example').append(lastlink);
                        } else {
                            $('span#example').append(link);
                        }
                    } else {
                        $('span#example').append(lastlink);
                    }

                });
            } else {
                $('span#example').append("<a href='search?searchTerm=" + example + "'>" + example + "</a>");
            }
        }
    });

    $('#search').prepend(searchForm);
}
function searchAllField(){
    let searchTerm = $('#searchTerm').val();
    searchTerm = searchTerm.trim();
    if(searchTerm!=""){
        let dbId = $('#dbId').val();
        if(dbId=='GSA'||dbId=='gsa'){
            let fl = document.forms['searchAllField'];
            fl.action="/gsa/search?searchTerm="+searchTerm;
            $("#searchAllField").submit();
        } else {
            window.location.href='https://ngdc.cncb.ac.cn/search/specific?db='+dbId+"&q="+searchTerm;
        }
        // else if(dbId=='BioProject') {
        //     let fl = document.forms['searchAllField'];
        //     fl.action="https://ngdc.cncb.ac.cn/bioproject/search?searchTerm="+searchTerm;
        //     $("#searchAllField").submit();
        // } else if(dbId=='BioSample') {
        //     let fl = document.forms['searchAllField'];
        //     fl.action="https://ngdc.cncb.ac.cn/biosample/search?searchTerm="+searchTerm;
        //     $("#searchAllField").submit();
        // }

    }
}
function searchAdvanced(){
    var fl = document.forms['searchAllField'];
    fl.action="/gsa/search/advanced";
    window.top.location.href = fl.action;
    //$("#searchAllField").submit();
}
